diff --git a/runtime/executors/claude/src/flush-log.test.ts b/runtime/executors/claude/src/flush-log.test.ts
index 26b304f..38ba635 100644
--- a/runtime/executors/claude/src/flush-log.test.ts
+++ b/runtime/executors/claude/src/flush-log.test.ts
@@ -298,3 +298,61 @@ describe("flushLog — SSH key wiring", () => {
     expect(env["GIT_SSH_COMMAND"]).toBeUndefined();
   });
 });
+
+// ── 9. LOG_SINK gating ────────────────────────────────────────────────────────
+
+describe("flushLog — LOG_SINK gating", () => {
+  afterEach(() => {
+    delete process.env["LOG_SINK"];
+  });
+
+  it("LOG_SINK=none → no git ops and no management repo writes", () => {
+    process.env["LOG_SINK"] = "none";
+    const wsRoot = makeTmpDir();
+    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
+    const events: Record<string, unknown>[] = [];
+
+    callFlushLog(wsRoot, { stdout: "some output" }, (e) => events.push(e));
+
+    expect(vi.mocked(execSync).mock.calls).toHaveLength(0);
+    expect(events).toHaveLength(0);
+  });
+
+  it("LOG_SINK=none → no log file written to management repo", () => {
+    process.env["LOG_SINK"] = "none";
+    const wsRoot = makeTmpDir();
+    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
+
+    callFlushLog(wsRoot, { stdout: "output" });
+
+    const safeIso = RUN_START_ISO.replace(/[:.]/g, "-");
+    const logPath = join(wsRoot, "docs", "features", FEATURE_ID, "logs", TASK_ID, `${safeIso}.jsonl`);
+    expect(() => readFileSync(logPath)).toThrow();
+  });
+
+  it("LOG_SINK=git → git flush proceeds (existing behaviour)", () => {
+    process.env["LOG_SINK"] = "git";
+    const wsRoot = makeTmpDir();
+    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
+
+    callFlushLog(wsRoot);
+
+    const pushCalls = vi.mocked(execSync).mock.calls.filter(([cmd]) =>
+      String(cmd).includes("push origin"),
+    );
+    expect(pushCalls).toHaveLength(1);
+  });
+
+  it("LOG_SINK absent → git flush proceeds (default behaviour)", () => {
+    delete process.env["LOG_SINK"];
+    const wsRoot = makeTmpDir();
+    vi.mocked(execSync).mockReturnValue(Buffer.from(""));
+
+    callFlushLog(wsRoot);
+
+    const pushCalls = vi.mocked(execSync).mock.calls.filter(([cmd]) =>
+      String(cmd).includes("push origin"),
+    );
+    expect(pushCalls).toHaveLength(1);
+  });
+});
